import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import ProcessGrid from './ProcessGrid';
import CreateProcessButton from './CreateProcessButton';
// import { fetchProcesses, createNewProcess } from '../../services/api'; // To be implemented

const HomePage = () => {
  const [processes, setProcesses] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  // Placeholder for API call - replace with actual fetchProcesses
  useEffect(() => {
    // setIsLoading(true);
    // fetchProcesses()
    //   .then(data => {
    //     setProcesses(data);
    //     setIsLoading(false);
    //   })
    //   .catch(err => {
    //     setError(err.message || 'Failed to fetch processes');
    //     setIsLoading(false);
    //   });
    // Using sample data from ProcessGrid for now
  }, []);

  const handleCreateProcess = async () => {
    setIsLoading(true);
    try {
      // const newProcess = await createNewProcess({ general_description: 'New Untitled Process' }); // API call
      // navigate(`/process/${newProcess.id}`);
      alert('Create new process clicked! Navigation to be implemented with API.');
      // For now, let's simulate creating a new process and navigating
      const newDummyId = `new-${Date.now()}`;
      navigate(`/process/${newDummyId}`);
    } catch (err) {
      setError(err.message || 'Failed to create process');
    } finally {
      setIsLoading(false);
    }
  };

  const filteredProcesses = processes.filter(proc => 
    (proc.title && proc.title.toLowerCase().includes(searchTerm.toLowerCase())) || 
    (proc.description && proc.description.toLowerCase().includes(searchTerm.toLowerCase()))
  );
  // If processes state is empty (e.g. API not implemented yet), ProcessGrid will use its own sample data
  const displayProcesses = searchTerm ? filteredProcesses : processes;

  const pageStyle = {
    padding: 'var(--spacing-unit, 16px)',
  };

  const controlsStyle = {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 'var(--spacing-unit, 16px)',
    flexWrap: 'wrap', // Allow controls to wrap on smaller screens
    gap: 'var(--spacing-unit, 16px)' // Gap between items
  };

  const searchInputStyle = {
    padding: '8px 12px',
    fontSize: '16px',
    border: '1px solid #ccc',
    borderRadius: 'var(--border-radius, 8px)',
    minWidth: '250px',
    flexGrow: 1 // Allow search to take available space
  };

  return (
    <div style={pageStyle}>
      <div style={controlsStyle}>
        <input 
          type="text" 
          placeholder="Search processes..." 
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={searchInputStyle}
        />
        <CreateProcessButton onClick={handleCreateProcess} />
      </div>

      {isLoading && <p>Loading...</p>}
      {error && <p style={{ color: 'red' }}>Error: {error}</p>}

      <ProcessGrid processes={displayProcesses.length > 0 || searchTerm ? displayProcesses : undefined} />
      {/* If displayProcesses is empty due to no API data AND no search term, 
          ProcessGrid will use its internal sample data. 
          If search yields no results from API data, it will show empty. 
      */}
    </div>
  );
};

export default HomePage;
